use vstd::prelude::*;

verus! {
    /// Returns the zero-based index of the last task.
    ///
    /// Under the problem assumptions:
    /// - n >= 2
    /// - m >= 1
    /// - tasks.len() == m as usize
    /// - each task ∈ [1, n]
    fn solve(n: i8, m: i8, tasks: Vec<i8>) -> (res: i8)
        requires
            // At least two machines, at least one task
            n >= 2,
            m >= 1,
            // tasks vector has exactly m elements
            tasks.len() == m as usize,
            // each task ID is between 1 and n inclusive
            forall |i: usize| (i < tasks.len() ==>
                1 <= tasks[i] && tasks[i] <= n),
        ensures
            // The result is the last task ID minus one
            res == tasks[tasks.len() - 1] - 1,
    {
        // Get the last task in the list (safe because tasks.len() >= 1)
        let last_task = *tasks.last().unwrap();
        // Subtract 1 to convert to zero-based index (safe because last_task >= 1)
        last_task - 1
    }
}

